<template><div class="table-wrap"><table><thead><tr><th>时间</th><th>账号</th><th>操作内容</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.id"><td class="audit-time">{{dateTime(entry.time)}}</td><td>{{entry.actor==='system'?'系统':entry.actor}}</td><td><strong>{{entry.action}}</strong><span v-if="summary(entry.detail)" class="audit-detail">{{summary(entry.detail)}}</span></td></tr></tbody></table></div></template><script setup lang="ts">import{dateTime}from'@/lib/product-format';defineProps<{entries:{id:string;time:number;actor:string;action:string;detail:unknown}[]}>();function summary(value:unknown){let detail=value;try{if(typeof detail==='string')detail=JSON.parse(detail)}catch{return''}if(!detail||typeof detail!=='object')return'';const d=detail as Record<string,unknown>;return[d.username,d.trackId,d.eventId,d.role].filter(x=>typeof x==='string').join(' · ')}</script><style scoped>.audit-time{white-space:nowrap;font-variant-numeric:tabular-nums}.audit-detail{display:block;color:#5f6b82;font-size:14px;margin-top:6px}strong{font-weight:500}</style>
